    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 amount, uint256 withdraw) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint hugeMin = type(uint256).max / 2;
        try c.SetMinSum(hugeMin) {} catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeEth = address(c).balance;
        bool reverted;
        try c.Collect(withdraw) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == beforeBal && address(c).balance == beforeEth);
    }

    function testFuzz_run(uint256 amount, uint256 withdraw) public {
        _run(amount, withdraw);
    }

    receive() external payable {}
}
